from langchain_google_genai import ChatGoogleGenerativeAI
from langchain_core.tools import tool, InjectedToolArg
from typing import Annotated

# 1. Define a tool with an injected argument
@tool
def get_user_balance(account_number: str, user_id: Annotated[str, InjectedToolArg]) -> str:
    """Get the account balance for a given account number."""
    # user_id is injected by the system, not generated by Gemini
    return f"User {user_id} has a balance of $5,000 in account {account_number}."

tools = [get_user_balance]

# 2. Initialize Gemini and bind tools
llm = ChatGoogleGenerativeAI(model="gemini-2.5-flash", temperature=0)
llm_with_tools = llm.bind_tools(tools)

# 3. Invoke the model
query = "What is my balance for account ACC-12345?"
ai_msg = llm_with_tools.invoke(query)

print("--- Model Tool Call (Notice user_id is absent) ---")
print(ai_msg.tool_calls)
# Output will only contain {"account_number": "ACC-12345"} because user_id is hidden from the LLM.

# 4. Programmatically inject the argument during execution
tool_map = {t.name: t for t in tools}

for tool_call in ai_msg.tool_calls:
    selected_tool = tool_map[tool_call["name"]]
    
    # Merge the LLM-generated arguments with your runtime/injected arguments
    execution_args = {
        **tool_call["args"], 
        "user_id": "user_98765"  # Injected programmatically from your backend session
    }
    
    tool_output = selected_tool.invoke(execution_args)
    print(f"\nTool Output: {tool_output}")